package report

import (
	"fmt"
	"strings"
	"time"
)

// MaxAttempts is how many times a flaky operation is tried.
const MaxAttempts = 3

// Backoff is the delay before the given attempt, doubling from 100ms.
func Backoff(attempt int) time.Duration {
	return 100 * time.Millisecond << attempt
}

// Summary renders label/count pairs one per line in the given order.
func Summary(counts map[string]int, order []string) string {
	var lines []string
	for _, label := range order {
		lines = append(lines, fmt.Sprintf("%s: %d", label, counts[label]))
	}
	return strings.Join(lines, "\n")
}

