package report

import "testing"

func TestSummaryFollowsGivenOrder(t *testing.T) {
	got := Summary(map[string]int{"ok": 2, "failed": 1}, []string{"failed", "ok"})
	if got != "failed: 1\nok: 2" {
		t.Fatalf("Summary = %q", got)
	}
}
